import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import sys
import tempfile

IDENTIFIER=re.compile('[a-z][a-z0-9_-]{0,31}')


def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def safe_bytes(path):
    with Path(path).open('rb') as stream:raw=stream.read(262145)
    if len(raw)>262144 or b'\0' in raw or b'\r' in raw:raise ValueError('input bytes')
    raw.decode('utf8');return raw


def atomic_new(path,value):
    path=Path(path);descriptor,temporary=tempfile.mkstemp(prefix='.json-',dir=path.parent)
    try:
        os.fchmod(descriptor,0o600)
        with os.fdopen(descriptor,'w',encoding='utf8') as stream:
            json.dump(value,stream,ensure_ascii=False,sort_keys=True,separators=(',',':'));stream.flush();os.fsync(stream.fileno())
        os.link(temporary,path)
    finally:
        if os.path.exists(temporary):os.unlink(temporary)


def assemble(input_path,spool,output):
    raw=Path(spool).read_bytes()
    if raw and not raw.endswith(b'\0'):raise ValueError('row spool framing')
    fields=raw[:-1].split(b'\0') if raw else []
    if len(fields)%4:raise ValueError('row spool cardinality')
    rows=[]
    for offset in range(0,len(fields),4):
        line,identifier,operation,payload=(part.decode('utf8') for part in fields[offset:offset+4])
        rows.append({'line':int(line),'id':identifier,'operation':operation,'payload':payload})
    atomic_new(output,{'schema':1,'input_sha256':sha(input_path),'rows':rows})


def compile_plan(input_path,output):
    environment=dict(os.environ,PYTHON=sys.executable,LC_ALL='C.UTF-8',PYTHONDONTWRITEBYTECODE='1')
    result=subprocess.run(['/bin/bash',str(Path(__file__).with_name('parse_manifest.sh')),str(input_path),str(output)],
                          env=environment,capture_output=True,timeout=5)
    if result.returncode or result.stdout:raise ValueError('whole manifest preflight failed')
    return json.loads(Path(output).read_text(encoding='utf8'))


def transformed(row):
    raw=row['payload'].encode('utf8')
    return raw if row['operation']=='literal' else raw.translate(bytes.maketrans(b'abcdefghijklmnopqrstuvwxyz',b'ABCDEFGHIJKLMNOPQRSTUVWXYZ'))


def _verify(snapshot,input_path=None):
    snapshot=Path(snapshot)
    if set(path.name for path in snapshot.iterdir())!={'input.bin','plan.json','manifest.json','files','inputs','receipts','logs'}:raise ValueError('snapshot layout')
    if any(path.is_symlink() for path in snapshot.rglob('*')):raise ValueError('snapshot symlink')
    if input_path is not None and Path(input_path).read_bytes()!=(snapshot/'input.bin').read_bytes():raise ValueError('input identity')
    with tempfile.TemporaryDirectory(prefix='.recheck-',dir=snapshot.parent) as folder:
        fresh=compile_plan(snapshot/'input.bin',Path(folder)/'fresh.json')
    plan=json.loads((snapshot/'plan.json').read_text(encoding='utf8'))
    if plan!=fresh or set(plan)!={'schema','input_sha256','rows'} or type(plan['schema']) is not int or plan['schema']!=1:raise ValueError('plan/input mismatch')
    manifest=json.loads((snapshot/'manifest.json').read_text())
    if set(manifest)!={'schema','input_sha256','plan_sha256','worker_sha256','records','files','receipts','logs'} or type(manifest['schema']) is not int or manifest['schema']!=1:raise ValueError('manifest schema')
    if manifest['input_sha256']!=sha(snapshot/'input.bin') or manifest['plan_sha256']!=sha(snapshot/'plan.json'):raise ValueError('source/plan digest')
    if not isinstance(manifest['worker_sha256'],str) or not re.fullmatch('[0-9a-f]{64}',manifest['worker_sha256']):raise ValueError('worker digest')
    rows=plan['rows'];identifiers=[]
    for number,row in enumerate(rows,1):
        if set(row)!={'line','id','operation','payload'} or type(row['line']) is not int or row['line']!=number or not IDENTIFIER.fullmatch(row['id']) or row['operation'] not in ('literal','upper') or not isinstance(row['payload'],str):raise ValueError('plan row schema')
        identifiers.append(row['id'])
    if len(set(identifiers))!=len(identifiers) or type(manifest['records']) is not int or manifest['records']!=len(rows):raise ValueError('record identity')
    expected={identifier+'.bin' for identifier in identifiers};receipt_names={identifier+'.json' for identifier in identifiers}
    log_names={identifier+'.'+channel for identifier in identifiers for channel in ('stdout','stderr')}
    for name,names in [('files',expected),('inputs',expected),('receipts',receipt_names),('logs',log_names)]:
        if not (snapshot/name).is_dir() or set(path.name for path in (snapshot/name).iterdir())!=names or any(not path.is_file() for path in (snapshot/name).iterdir()):raise ValueError('record file set')
    if set(manifest['files'])!=expected or set(manifest['receipts'])!=receipt_names or set(manifest['logs'])!=log_names:raise ValueError('manifest record set')
    for row in rows:
        identifier=row['id'];input_file=snapshot/'inputs'/(identifier+'.bin');output_file=snapshot/'files'/(identifier+'.bin');receipt_file=snapshot/'receipts'/(identifier+'.json')
        if input_file.read_bytes()!=row['payload'].encode('utf8') or output_file.read_bytes()!=transformed(row):raise ValueError('business bytes')
        receipt=json.loads(receipt_file.read_text())
        if set(receipt)!={'schema','id','operation','input_sha256','output_sha256','output_size','exit_status'} or type(receipt['schema']) is not int or receipt['schema']!=1:raise ValueError('receipt schema')
        if receipt['id']!=identifier or receipt['operation']!=row['operation'] or receipt['input_sha256']!=sha(input_file) or receipt['output_sha256']!=sha(output_file):raise ValueError('receipt identity/digest')
        if type(receipt['output_size']) is not int or receipt['output_size']!=output_file.stat().st_size or type(receipt['exit_status']) is not int or receipt['exit_status']!=0:raise ValueError('receipt numbers')
        if manifest['files'][identifier+'.bin']!=sha(output_file) or manifest['receipts'][identifier+'.json']!=sha(receipt_file):raise ValueError('record digests')
    for filename,digest in manifest['logs'].items():
        if sha(snapshot/'logs'/filename)!=digest:raise ValueError('worker log digest')
